 "content": "def transform(grid):
    """Extend the three-color top marker downward, linking same-color edge markers."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The pattern is the three adjacent non-background cells along the top edge.
    seeds = [(c, grid[0][c]) for c in range(w) if grid[0][c] != 0]
    for col, color in seeds:
        # A matching marker on a side edge limits the vertical ray and gets joined
        # horizontally to the seed's column. With no marker, extend to the bottom.
        edge_markers = [(r, 0) for r in range(1, h) if grid[r][0] == color]
        edge_markers += [(r, w - 1) for r in range(1, h) if grid[r][w - 1] == color]
        if edge_markers:
            row, edge_col = edge_markers[0]
            for r in range(min(row, h - 1) + 1):
                out[r][col] = color
            for c in range(min(col, edge_col), max(col, edge_col) + 1):
                out[row][c] = color
        else:
            for r in range(h):
                out[r][col] = color
    return out


